# owner: platform
import unittest

from hourglass.rounding import round_spans
from hourglass.models import Span


class RoundSpansTests(unittest.TestCase):
    def test_snaps_to_nearest_step(self):
        span = Span(9 * 60 + 4, 17 * 60 + 10)
        self.assertEqual(
            round_spans([span], 15),
            ["09:00-17:15 (8h 15m)"]
        )

    def test_halves_round_up(self):
        span = Span(9 * 60 + 7, 10 * 60 + 22)
        self.assertEqual(
            round_spans([span], 15),
            ["09:00-10:15 (1h 15m)"]
        )

    def test_one_label_per_span(self):
        spans = [Span(0, 60), Span(60, 90)]
        self.assertEqual(
            round_spans(spans, 30),
            ["00:00-01:00 (1h 0m)", "01:00-01:30 (0h 30m)"]
        )

    def test_bad_steps_raise(self):
        for step in (0, -15, 7, 45):
            with self.assertRaises(ValueError):
                round_spans([Span(0, 60)], step)


if __name__ == "__main__":
    unittest.main()
